import{_ as t,c as a,o as i,a5 as n}from"./chunks/framework.BmNIwhaK.js";const h=JSON.parse(`{"title":"Story Points","description":"Story points are a relative unit for estimating the size, complexity, and uncertainty of work. They do not map directly to absolute time and are designed to help gauge reasonable sprint workloads and estimate team schedules.","frontmatter":{"title":"Story Points","description":"Story points are a relative unit for estimating the size, complexity, and uncertainty of work. They do not map directly to absolute time and are designed to help gauge reasonable sprint workloads and estimate team schedules.","head":[["meta",{"name":"keywords","content":"Scrumban, Scrumban introduction, Scrumban concept, what is Scrumban, Scrumban overview, Scrumban fundamentals, Scrum vs Kanban differences, Scrum vs Kanban, agile methodology, agile framework, Kanban methodology, Scrum methodology, Scrumban process, Scrumban operations guide, Scrumban board, WIP limits, workflow management, how to use a Kanban board, Scrumban benefits, Scrumban characteristics, Scrumban impact, Scrumban use cases, Scrumban adoption benefits, Scrumban Jira setup, Scrumban board template, Scrumban tools, Scrumban collaboration tools, Scrumban workflow, agile project management, work efficiency methodology, iterative work management, bottleneck resolution"}],["meta",{"property":"og:title","content":"Scrumban"}],["meta",{"property":"og:description","content":"Scrumban is a hybrid agile methodology that combines Scrum's iterative structure with Kanban's flow management and WIP limits to manage work flexibly and efficiently."}],["meta",{"property":"og:image","content":"https://doc.empasy.com/images/favicon.png"}],["meta",{"property":"og:url","content":"https://doc.empasy.com/en/agile/storyPointGuide"}],["link",{"rel":"canonical","href":"https://doc.empasy.com/en/agile/storyPointGuide"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://doc.empasy.com/agile/storyPointGuide"}],["link",{"rel":"alternate","hreflang":"en","href":"https://doc.empasy.com/en/agile/storyPointGuide"}],["link",{"rel":"alternate","hreflang":"ja","href":"https://doc.empasy.com/ja/agile/storyPointGuide"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://doc.empasy.com/agile/storyPointGuide"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:site_name","content":"Empasy Docs"}],["meta",{"property":"og:title","content":"Story Points | Empasy Docs"}],["meta",{"property":"og:description","content":"Story points are a relative unit for estimating the size, complexity, and uncertainty of work. They do not map directly to absolute time and are designed to help gauge reasonable sprint workloads and estimate team schedules."}],["meta",{"property":"og:url","content":"https://doc.empasy.com/en/agile/storyPointGuide"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Story Points | Empasy Docs"}],["meta",{"name":"twitter:description","content":"Story points are a relative unit for estimating the size, complexity, and uncertainty of work. They do not map directly to absolute time and are designed to help gauge reasonable sprint workloads and estimate team schedules."}]],"sort":2000},"headers":[],"relativePath":"en/agile/storyPointGuide.md","filePath":"en/agile/storyPointGuide.md","lastUpdated":1795293539000}`),o={name:"en/agile/storyPointGuide.md"};function r(s,e,l,c,d,m){return i(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="story-point-guide-how-agile-teams-estimate-work" tabindex="-1">Story Point Guide: How Agile Teams Estimate Work <a class="header-anchor" href="#story-point-guide-how-agile-teams-estimate-work" aria-label="Permalink to “Story Point Guide: How Agile Teams Estimate Work”">​</a></h1><h2 id="what-are-story-points" tabindex="-1">What Are Story Points? <a class="header-anchor" href="#what-are-story-points" aria-label="Permalink to “What Are Story Points?”">​</a></h2><p>Story points are a unit for relatively estimating the <strong>size, complexity, and uncertainty</strong> of work. They do not map directly to absolute time and are intended to help gauge reasonable sprint workloads and estimate team schedules.</p><blockquote><p>The approach that &quot;5 points = 5 times the hours of 1 point&quot; is incorrect.</p></blockquote><h2 id="why-use-the-fibonacci-sequence" tabindex="-1">Why Use the Fibonacci Sequence? <a class="header-anchor" href="#why-use-the-fibonacci-sequence" aria-label="Permalink to “Why Use the Fibonacci Sequence?”">​</a></h2><p>Story point estimation commonly uses a Fibonacci-like sequence such as <strong>1, 2, 3, 5, 8, 13, 21...</strong>. The reasons for using this non-consecutive sequence are:</p><ul><li>The widening intervals reflect growing uncertainty</li><li>The difference between 5 and 8 is clearer than between 5 and 6</li><li>It reflects that complexity and risk grow exponentially as tasks get larger</li><li>As a result, team consensus becomes easier and over- or under-estimation is reduced</li></ul><h2 id="story-point-usage-examples" tabindex="-1">Story Point Usage Examples <a class="header-anchor" href="#story-point-usage-examples" aria-label="Permalink to “Story Point Usage Examples”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Task Item</th><th style="text-align:left;">Points</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;">User Research</td><td style="text-align:left;">3 points</td><td style="text-align:left;">Work requiring relatively light effort</td></tr><tr><td style="text-align:left;">Wireframing</td><td style="text-align:left;">5 points</td><td style="text-align:left;">Straightforward work conducted after user research</td></tr><tr><td style="text-align:left;">UI Design</td><td style="text-align:left;">8 points</td><td style="text-align:left;">Work requiring alignment within the team</td></tr><tr><td style="text-align:left;">Development Work</td><td style="text-align:left;">13 points</td><td style="text-align:left;">Complex work involving many interacting components</td></tr><tr><td style="text-align:left;">QA Testing</td><td style="text-align:left;">8 points</td><td style="text-align:left;">Complex but manageable level of work</td></tr></tbody></table><h2 id="reference-task-examples" tabindex="-1">Reference Task Examples <a class="header-anchor" href="#reference-task-examples" aria-label="Permalink to “Reference Task Examples”">​</a></h2><h3 id="story-points-5-user-password-reset-feature" tabindex="-1">Story Points 5: User Password Reset Feature <a class="header-anchor" href="#story-points-5-user-password-reset-feature" aria-label="Permalink to “Story Points 5: User Password Reset Feature”">​</a></h3><p><strong>Definition of Done</strong></p><ul><li>Implement password change functionality</li><li>Implement email verification functionality</li><li>Enforce password rules (alphanumeric, etc.)</li></ul><p><strong>Additional Considerations</strong></p><ul><li>Database table design</li><li>Email sending/receiving environment</li><li>Edge-case exceptions do not need to be considered</li></ul><h3 id="story-points-13-credit-card-payment-feature" tabindex="-1">Story Points 13: Credit Card Payment Feature <a class="header-anchor" href="#story-points-13-credit-card-payment-feature" aria-label="Permalink to “Story Points 13: Credit Card Payment Feature”">​</a></h3><p><strong>Definition of Done</strong></p><ul><li>Implement product payment functionality</li><li>Enable viewing purchase history on My Page</li><li>Enable administrator visibility as well</li></ul><p><strong>Additional Considerations</strong></p><ul><li>Card registration functionality already exists</li><li>Database design required</li><li>Error patterns do not need to be considered</li></ul><h2 id="caution-incorrect-usage" tabindex="-1">Caution: Incorrect Usage <a class="header-anchor" href="#caution-incorrect-usage" aria-label="Permalink to “Caution: Incorrect Usage”">​</a></h2><p><strong>Avoid mapping directly to hours</strong></p><ul><li>&quot;A 4-hour task = 1 point&quot; → no different from traditional time-based estimation</li><li>&quot;5 points = 5 times the hours of 1 point&quot;</li></ul><p><strong>Correct meaning</strong>: It means the task is 5 times more complex than a 1-point task. Equating points to hours undermines the core purpose of story points.</p><h2 id="refactoring-and-quality-considerations" tabindex="-1">Refactoring and Quality Considerations <a class="header-anchor" href="#refactoring-and-quality-considerations" aria-label="Permalink to “Refactoring and Quality Considerations”">​</a></h2><p>Every story must include both of the following elements:</p><ol><li>Functionality that <strong>works properly</strong></li><li>Quality that <strong>works the right way</strong></li></ol><p>Satisfying only the first element while ignoring the second leaves the story points incomplete. Refactoring work can also be assigned points from the perspective of improving quality (eliminating technical debt).</p><blockquote><p>Caution: Never use story points to compare individual performance. They are strictly a team-level tool.</p></blockquote><h2 id="key-takeaways" tabindex="-1">Key Takeaways <a class="header-anchor" href="#key-takeaways" aria-label="Permalink to “Key Takeaways”">​</a></h2><ul><li>Story points are a <strong>relative estimation unit</strong></li><li>The goal is <strong>comparing complexity and uncertainty</strong>, not converting to hours</li><li>Using the Fibonacci sequence accounts for higher risk in larger tasks</li><li>Establish team reference baselines (such as 3, 5, 8, and 13) and estimate new work by comparing against them</li><li>Avoid incorrect time-mapping practices and always factor in quality standards</li></ul><hr><h1 id="story-point-estimation-meeting-guide" tabindex="-1">Story Point Estimation Meeting Guide <a class="header-anchor" href="#story-point-estimation-meeting-guide" aria-label="Permalink to “Story Point Estimation Meeting Guide”">​</a></h1><h2 id="meeting-agenda" tabindex="-1">Meeting Agenda <a class="header-anchor" href="#meeting-agenda" aria-label="Permalink to “Meeting Agenda”">​</a></h2><h3 id="opening-5-minutes" tabindex="-1">Opening (5 minutes) <a class="header-anchor" href="#opening-5-minutes" aria-label="Permalink to “Opening (5 minutes)”">​</a></h3><ul><li>Explain the meeting goal: relatively estimate the difficulty and complexity of work for the upcoming sprint</li><li>Emphasize reaching consensus through relative size comparison rather than absolute time units</li></ul><h3 id="basic-concept-reminder-10-minutes" tabindex="-1">Basic Concept Reminder (10 minutes) <a class="header-anchor" href="#basic-concept-reminder-10-minutes" aria-label="Permalink to “Basic Concept Reminder (10 minutes)”">​</a></h3><ul><li>Definition of story points: a unit representing the size, complexity, and uncertainty of work</li><li>Do not map 1:1 to hours (&quot;5 points = 5 times the hours of 1 point&quot;)</li><li>Explain why the Fibonacci sequence is used (1, 2, 3, 5, 8, 13, 21...)</li></ul><h3 id="sharing-reference-examples-10-minutes" tabindex="-1">Sharing Reference Examples (10 minutes) <a class="header-anchor" href="#sharing-reference-examples-10-minutes" aria-label="Permalink to “Sharing Reference Examples (10 minutes)”">​</a></h3><ul><li>Share story point examples (User Research → 3, Wireframing → 5, etc.)</li><li>Review concrete reference tasks (5 points: Password Reset, 13 points: Credit Card Payment)</li></ul><h3 id="caution-against-incorrect-usage-5-minutes" tabindex="-1">Caution Against Incorrect Usage (5 minutes) <a class="header-anchor" href="#caution-against-incorrect-usage-5-minutes" aria-label="Permalink to “Caution Against Incorrect Usage (5 minutes)”">​</a></h3><ul><li>Emphasize not substituting hours directly</li><li>&quot;5 points = 5 times the hours of 1 point&quot;</li><li>Correct interpretation: &quot;5 times more complex than 1 point&quot;</li></ul><h3 id="refactoring-and-quality-considerations-10-minutes" tabindex="-1">Refactoring and Quality Considerations (10 minutes) <a class="header-anchor" href="#refactoring-and-quality-considerations-10-minutes" aria-label="Permalink to “Refactoring and Quality Considerations (10 minutes)”">​</a></h3><ul><li>Every story must include [1] working functionality + [2] working the right way (quality)</li><li>Assign points to refactoring and technical debt reduction as appropriate</li><li>Reiterate that story points are not for comparing individual performance</li></ul><h3 id="actual-work-estimation-30–40-minutes" tabindex="-1">Actual Work Estimation (30–40 minutes) <a class="header-anchor" href="#actual-work-estimation-30–40-minutes" aria-label="Permalink to “Actual Work Estimation (30–40 minutes)”">​</a></h3><ul><li>Review backlog items one by one</li><li>Discuss by comparing against reference examples</li><li>Team consensus → select a Fibonacci number (e.g., 3, 5, 8, 13)</li><li>Work toward consensus when issues or differing opinions arise</li></ul><h3 id="wrap-up-5-minutes" tabindex="-1">Wrap-Up (5 minutes) <a class="header-anchor" href="#wrap-up-5-minutes" aria-label="Permalink to “Wrap-Up (5 minutes)”">​</a></h3><ul><li>Summarize the story point estimates decided during the meeting</li><li>Announce that they will be incorporated into the next sprint plan</li><li>Reiterate that &quot;story points are a tool to help the team estimate schedules quickly and easily&quot;</li></ul><p>Story points are a valuable tool for team productivity and schedule management, but they deliver their true value only when understood and applied properly.</p>',49)])])}const p=t(o,[["render",r]]);export{h as __pageData,p as default};
